-- Farm
UPDATE Language_ru_RU
SET Text = 'Фермы можно строить почти на любой суше, чтобы увеличить производство пищи на клетке. Фермы получают +1 пищу за каждые две соседние фермы и/или при наличии пресной воды.[NEWLINE][NEWLINE]Земледелие — одна из древнейших и важнейших профессий человечества, поскольку именно оно позволило людям перестать кочевать и осесть на одном месте, не истощая местные ресурсы.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_FARM_TEXT';

-- Mine
UPDATE Language_ru_RU
SET Text = 'Шахты — одни из важнейших улучшений в Civilization V. Они не только увеличивают производительность клетки — а высокая производительность позволяет быстрее строить юниты, здания и чудеса, — но и дают доступ к некоторым из важнейших ресурсов игры: железу, углю и алюминию, если назвать лишь несколько.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_MINE_TEXT';

-- Lumber Mill
UPDATE Language_ru_RU
SET Text = 'Лесопилка позволяет увеличить производство и золото на клетках леса и джунглей. Она получает дополнительное золото и производство за каждые две соседние лесопилки, поэтому по возможности старайтесь строить их группами по три.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_LUMBERMILL_TEXT';

UPDATE Language_ru_RU
SET Text = 'Это увеличит [ICON_PRODUCTION] производство (в лесу) или [ICON_GOLD] золото (в джунглях), которое даёт эта клетка, сохранив при этом лес/джунгли нетронутыми. Лесопилка, соседствующая с двумя другими лесопилками, получает +1 [ICON_PRODUCTION] производства и [ICON_GOLD] золота.'
WHERE Tag = 'TXT_KEY_BUILD_LUMBERMILL_REC';

-- Village
UPDATE Language_ru_RU
SET Text = 'Деревня'
WHERE Tag = 'TXT_KEY_IMPROVEMENT_TRADING_POST';

UPDATE Language_ru_RU
SET Text = 'Деревни — это небольшие поселения, разбросанные по сельской местности цивилизации, символизирующие людей, живущих за счёт земли и торговли. Они могут приносить обществу значительное богатство, особенно если расположены на дорогах, железных дорогах или торговых путях.[NEWLINE][NEWLINE]Получают [ICON_GOLD] золото и [ICON_PRODUCTION] производство, если построены на дороге или железной дороге, соединяющей два ваших города.[NEWLINE][NEWLINE]Получают дополнительное [ICON_GOLD] золото и [ICON_PRODUCTION] производство (+1 до Индустриальной эпохи, +2 в Индустриальную эпоху и позже), если через эту деревню проходит торговый путь — внутренний или международный.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_TRADING_POST_TEXT';

UPDATE Language_ru_RU
SET Text = 'Построить [LINK=IMPROVEMENT_TRADING_POST]деревню[\LINK]'
WHERE Tag = 'TXT_KEY_BUILD_TRADING_POST';

-- Fort
UPDATE Language_ru_RU
SET Text = 'Форт — это особое улучшение, увеличивающее оборонительный бонус клетки на 50% для юнитов, находящихся на ней. Однако форты не дают оборонительного бонуса юнитам на вражеской территории. Не могут строиться рядом друг с другом. Содержит [COLOR_POSITIVE_TEXT]укрепления[ENDCOLOR], позволяющие вашим юнитам оставаться на этой клетке после атаки, а также [COLOR_POSITIVE_TEXT]канал[ENDCOLOR], позволяющий дружественным [COLOR_POSITIVE_TEXT]морским[ENDCOLOR] юнитам проходить через него.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_FORT_TEXT';

UPDATE Language_ru_RU
SET Text = '+50% [ICON_STRENGTH] к защитной силе любого юнита, находящегося на этой клетке. Содержит [COLOR_POSITIVE_TEXT]укрепления[ENDCOLOR], позволяющие вашим юнитам оставаться на этой клетке после атаки, а также [COLOR_POSITIVE_TEXT]канал[ENDCOLOR], позволяющий дружественным [COLOR_POSITIVE_TEXT]морским[ENDCOLOR] юнитам проходить через него.'
WHERE Tag = 'TXT_KEY_BUILD_FORT_HELP';

-- Town
UPDATE Language_ru_RU
SET Text = 'Городок'
WHERE Tag = 'TXT_KEY_IMPROVEMENT_CUSTOMS_HOUSE';

UPDATE Language_ru_RU
SET Text = '{TXT_KEY_CIV5_IMPROVEMENTS_CUSTOMS_HOUSE_HELP}[NEWLINE][NEWLINE]Городок — это населённый пункт крупнее деревни, но меньше города. То, что считается «городком», в разных частях мира определяется по-разному. Слово town родственно немецкому Zaun, голландскому tuin и древнескандинавскому tun. Немецкое Zaun ближе всего к исходному значению слова: ограда из любого материала.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_CUSTOMS_HOUSE_TEXT';

UPDATE Language_ru_RU
SET Text = 'Построить [LINK=IMPROVEMENT_CUSTOMS_HOUSE]городок[\LINK]'
WHERE Tag = 'TXT_KEY_BUILD_CUSTOMS_HOUSE';

-- Academy
UPDATE Language_ru_RU
SET Text = '{TXT_KEY_CIV5_IMPROVEMENTS_ACADEMY_HELP}[NEWLINE][NEWLINE]Академия — это учреждение, где дети получают углублённое среднее (то есть допрофессиональное) образование. Академии бывают самых разных видов — военные, религиозные, государственные и прочие. Некоторые частные и открыты лишь детям богатых, влиятельных или властных людей, другие доступны всем, кто соответствует строгим требованиям. Одной из самых известных академий мира является английский Итонский колледж, принимающий мальчиков в возрасте от 13 до 18 лет с 1440 года.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_ACADEMY_TEXT';

-- Manufactory
UPDATE Language_ru_RU
SET Text = '{TXT_KEY_CIV5_IMPROVEMENTS_MANUFACTORY_HELP}[NEWLINE][NEWLINE]Мануфактура — это предприятие, состоящее из одного или нескольких зданий, в которых производятся товары. Это могут быть литейные цеха, фабрики, сборочные линии и т. п., обычно все они работают над связанными товарами: литейный цех производит сталь, фабрика прокатывает её в листы, а рабочие на сборочной линии делают из них, например, банки. Хорошо управляемая мануфактура может быть невероятно производительной.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_MANUFACTORY_TEXT';

-- Citadel
UPDATE Language_ru_RU
SET Text = 'Цитадель — могучее укрепление, которое может быть построено только Великим генералом, обычно рядом с городом или на особенно выгодной для обороны местности. Акрополь в Афинах — пример ранней мощной цитадели. Такие сооружения было почти невозможно взять прямым штурмом, и они могли выдерживать долгие осады.[NEWLINE][NEWLINE]Вы можете построить цитадель где угодно на своей территории или прямо рядом с ней. После строительства лимит военного снабжения увеличивается на 1, а ваши культурные границы расширяются на одну клетку во все стороны вокруг цитадели. Если новая культурная граница захватывает клетки, уже принадлежащие другой цивилизации, это вызовет дипломатический штраф. Любой юнит, находящийся в цитадели, получает 100% бонус к защите. Кроме того, любой вражеский юнит, заканчивающий ход рядом с цитаделью, получает 30 урона (урон не суммируется с другими цитаделями). Содержит [COLOR_POSITIVE_TEXT]укрепления[ENDCOLOR], позволяющие вашим юнитам оставаться на этой клетке после атаки, а также [COLOR_POSITIVE_TEXT]канал[ENDCOLOR], позволяющий дружественным [COLOR_POSITIVE_TEXT]морским[ENDCOLOR] юнитам проходить через него.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_CITADEL_TEXT';

UPDATE Language_ru_RU
SET Text = 'Может быть построена только на вашей территории или на нейтральной клетке, примыкающей к вашим границам, и не может находиться рядом с другими цитаделями. Строительство цитадели расширит ваши культурные границы вокруг неё, увеличит [ICON_WAR] лимит военного снабжения на 1 и израсходует этого юнита. Если новая культурная граница захватывает клетки, уже принадлежащие другой цивилизации, вы получите дипломатический штраф.[NEWLINE][NEWLINE]+100% [ICON_STRENGTH] к защитной силе любого юнита, находящегося на этой клетке. Любой вражеский юнит, заканчивающий ход рядом с этой клеткой, получает 30 урона (урон не суммируется с другими улучшениями). Содержит [COLOR_POSITIVE_TEXT]укрепления[ENDCOLOR], позволяющие вашим юнитам оставаться на этой клетке после атаки, а также [COLOR_POSITIVE_TEXT]канал[ENDCOLOR], позволяющий дружественным [COLOR_POSITIVE_TEXT]морским[ENDCOLOR] юнитам проходить через него.'
WHERE Tag = 'TXT_KEY_BUILD_CITADEL_HELP';

-- Holy Site
UPDATE Language_ru_RU
SET Text = 'Юнит будет израсходован.[NEWLINE][NEWLINE]Даёт дополнительную 1 [ICON_PEACE] веру за каждую соседнюю гору.[NEWLINE][NEWLINE]Подключает ресурсы на этой клетке к торговой сети.'
WHERE Tag = 'TXT_KEY_BUILD_HOLY_SITE_HELP';

UPDATE Language_ru_RU
SET Text = '{TXT_KEY_CIV5_IMPROVEMENTS_HOLY_SITE_HELP}[NEWLINE][NEWLINE]Святое место — это место религиозной значимости, почитаемое как свидетельство богов, пророков и традиций определённой религии. Часто являясь целью паломников, такие места посещаются верующими в надежде укрепить свою связь с Богом и отдать дань уважения святыне.'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_HOLY_SITE_TEXT';

-- Landmark
UPDATE Language_ru_RU
SET Text = 'Достопримечательности при строительстве дают по +3 [ICON_HAPPINESS_1] счастья во всей империи команде строителя и команде владельца клетки (максимум +3 за достопримечательность для каждой команды), а также +1 [ICON_CULTURE] культуры и +1 [ICON_GOLD] золота на этой клетке за каждую дополнительную эпоху, прошедшую с момента появления артефакта.[NEWLINE][NEWLINE]Достопримечательностью может быть любой выдающийся артефакт, сооружение, произведение искусства или чудо природы, привлекающее посетителей в определённое место. Колонна Нельсона в Лондоне — достопримечательность, как и гора Рашмор в США. Однако не всякий крупный объект становится достопримечательностью: крупнейший в мире клубок шпагата может так и не достичь этого статуса (хотя посмотреть на него, возможно, и стоит).'
WHERE Tag = 'TXT_KEY_CIV5_IMPROVEMENTS_LANDMARK_TEXT';

-- Barbarian Encampment
UPDATE Language_ru_RU
SET Text = 'Лагерь варваров'
WHERE Tag = 'TXT_KEY_IMPROVEMENT_ENCAMPMENT';

UPDATE Language_ru_RU
SET Text = 'Лагерь варваров — это временное поселение группы свирепых варваров, стремящихся сокрушить и уничтожить вашу цивилизацию. Эти вечные занозы в боку цивилизованных народов способны бесконечно порождать разъярённых варваров, жаждущих захватить ваши города, разграбить ваши земли и похотливо глазеть на ваших женщин. Лагеря рядом с вашими городами следует уничтожать без всяких колебаний. Лагеря, находящиеся ближе к соперничающим цивилизациям, можно оставить, чтобы они досаждали вашим врагам — если вы, конечно, такой коварный правитель...'
WHERE Tag = 'TXT_KEY_IMPROVEMENT_BARBARIAN_CAMP_PEDIA';
